CREATE DEFINER=`root`@`localhost` FUNCTION `hrms_pay_days`(p_unpaid_days DECIMAL(6,2)) RETURNS decimal(5,2)
    NO SQL
    DETERMINISTIC
BEGIN
    RETURN GREATEST(30 - GREATEST(COALESCE(p_unpaid_days, 0), 0), 0);
END ;;
