CREATE DEFINER=`root`@`localhost` PROCEDURE `getactiveUsersfordropdown`()
BEGIN
    SELECT 
        ud.emp_id, 
        ud.emp_name 
    FROM 
        user_details ud
    INNER JOIN 
        user_login_details uld ON ud.emp_id = uld.emp_id
    WHERE 
        uld.status = 'Active';
END ;;
