                AS remarks;

    ELSE


        

        SET v_period_start =
            DATE_SUB(
                STR_TO_DATE(
                    CONCAT(p_year, '-', p_month, '-25'),
                    '%Y-%m-%d'
                ),
                INTERVAL 1 MONTH
            );


        SET v_period_end =
            STR_TO_DATE(
                CONCAT(p_year, '-', p_month, '-24'),
                '%Y-%m-%d'
            );


        

        IF v_today < v_period_end THEN

            SET v_calculation_end = v_today;

        ELSE

            SET v_calculation_end = v_period_end;

        END IF;


        

        SELECT
            (
                DATEDIFF(
                    v_calculation_end,
                    v_period_start
                ) + 1
            )
            -
            COUNT(DISTINCT hm.holiday_date)

        INTO v_total_working_days

        FROM holiday_master hm

        WHERE hm.holiday_date
              BETWEEN v_period_start
              AND v_calculation_end

          AND hm.status = 'A';


        

        SELECT COUNT(*)
        INTO v_employee_count

        FROM user_details ud

        INNER JOIN user_login_details uld
            ON uld.emp_id = ud.emp_id

        WHERE ud.reporting = p_emp_id
          AND uld.status = 'ACTIVE';


        

        IF v_employee_count = 0 THEN

            SELECT
                'N' AS status,

                'There are no employees reporting to this employee'
                    AS remarks,

                p_emp_id AS reporting_to,

                v_period_start AS period_start,

                v_period_end AS period_end,

                v_calculation_end AS calculated_until;


        ELSE


            

            SELECT

                'Y' AS status,

                'Attendance period summary fetched successfully'
                    AS remarks,


                

                ud.emp_id
                    AS emp_id,

                ud.emp_name
                    AS employee_name,


                

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.status = 'PRESENT'
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS total_present,


                

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.status = 'WFH'
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS total_wfh,


                

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.status = 'LEAVE'
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS total_leaves,


                

                COALESCE(
                    SUM(
                        CASE
                            WHEN a.punch_in IS NOT NULL
                             AND a.punch_out IS NOT NULL
                             AND a.punch_in = a.punch_out
                            THEN 1
                            ELSE 0
                        END
                    ),
                    0
                ) AS missed_punch,


                

                COALESCE(

                    SEC_TO_TIME(
                        SUM(
                            CASE

                                WHEN a.punch_in IS NOT NULL
                                 AND a.punch_out IS NOT NULL
                                 AND a.punch_out > a.punch_in

                                THEN TIMESTAMPDIFF(
                                    SECOND,
                                    a.punch_in,
                                    a.punch_out
                                )

                                ELSE 0

                            END
                        )
                    ),

                    '00:00:00'

                ) AS total_hours,


                

                v_total_working_days
                    AS total_working_days,


                

                GREATEST(

                    v_total_working_days

                    - COALESCE(
                        SUM(
                            CASE
                                WHEN a.status IN ('PRESENT', 'WFH')
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    )

                    - COALESCE(
                        SUM(
                            CASE
                                WHEN a.status = 'LEAVE'
                                THEN 1
                                ELSE 0
                            END
                        ),
                        0
                    ),

                    0

                ) AS total_absents,


                

                v_period_start
                    AS period_start,

                v_period_end
                    AS period_end,

                v_calculation_end
                    AS calculated_until


            FROM user_details ud

            INNER JOIN user_login_details uld
                ON uld.emp_id = ud.emp_id


            LEFT JOIN attendance a
                ON a.emp_id = ud.emp_id

               AND a.attendance_date
                   BETWEEN v_period_start
                   AND v_calculation_end


            WHERE ud.reporting = p_emp_id
              AND uld.status = 'ACTIVE'


            GROUP BY
                ud.emp_id,
                ud.emp_name


            ORDER BY
                ud.emp_id;


        END IF;

    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
