CREATE DEFINER=`root`@`localhost` PROCEDURE `get_candidate_details_by_ref_id`(

    IN p_ref_id VARCHAR(20)

)
BEGIN

    DECLARE v_count INT DEFAULT 0;

    SET time_zone = '+05:30';

    

    SELECT COUNT(*) INTO v_count
    FROM candidate_details
    WHERE ref_id = p_ref_id;

    IF v_count > 0 THEN

        

        SELECT

            'Y' AS status,

            id,

            ref_id,

            candidate_type,

            application_source,

            resume_url,

            offer_letter_url,

            temp_password,

            offer_status,

            onboarding_status,

            hr_status,

            current_step,

            is_submitted,

            emp_name,

            email,

            mobile,

            dob,

            gender,

            marital_status,

            father_name,

            mother_name,

            current_address,

            perminent_address,

            bank_holder_name,

            bank_name,

            bank_branch,

            bank_account_no,

            ifsc,

            upi_id,

            bank_account_type,

            pan,

            aadhaar,

            uan,

            skills,

            qualification,

            department,

            designation,

            reporting,

            remarks,

            created_by,

            received_on,

            updated_on,

            documents,
            experience

        FROM candidate_details
        WHERE ref_id = p_ref_id;

    ELSE

        SELECT

            'N' AS status,

            p_ref_id AS ref_id,

            'candidate not found' AS remarks;

    END IF;

END ;;
DELIMITER ;
