CREATE DEFINER=`root`@`localhost` PROCEDURE `hr_get_leave_history`(
    IN p_emp_id VARCHAR(20)
)
main_block:BEGIN

    DECLARE v_record_count INT DEFAULT 0;

    SET time_zone='+05:30';

    
    SELECT COUNT(*) INTO v_record_count
    FROM leave_application
    WHERE emp_id = p_emp_id;

    
    IF v_record_count = 0 THEN
        SELECT 'N' AS status, 'leave history not available' AS remarks;
        LEAVE main_block;
    END IF;

    
    SELECT
        'Y' AS status,
        'Success' AS remarks,
        l.leave_app_id,
        l.emp_id,
        u.emp_name,
        lt.leave_type_id,
        lt.leave_code,
        lt.leave_name,
        l.from_date,
        l.to_date,
        l.total_days,
        l.applied_days,
        l.reason,
        l.status AS leave_status,
        l.applied_on,
        l.approved_by,
        IFNULL(a.emp_name,'') AS approved_by_name,
        l.approved_on,
        l.rejection_reason,
        l.cancel_reason,
        l.received_on,
        l.updated_on
    FROM leave_application l
    INNER JOIN user_details u ON u.emp_id = l.emp_id
    INNER JOIN leave_type lt ON lt.leave_type_id = l.leave_type_id
    LEFT JOIN user_details a ON a.emp_id = l.approved_by
    WHERE
        l.emp_id = p_emp_id
    ORDER BY
        l.applied_on DESC,
        l.from_date DESC,
        l.leave_app_id DESC;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
