/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `hr_get_leave_types`()
BEGIN

    SET time_zone='+05:30';

    SELECT 
        'Y' AS status,
        'Success' AS remarks,
        lt.leave_type_id,
        lt.leave_code,
        lt.leave_name,
        lt.year,
        lt.yearly_quota,
        lt.carry_forward_flag,
        lt.max_carry_forward,
        lt.encashment_flag,
        lt.requires_approval,
        lt.affects_salary,
        lt.gender_applicable,
        lt.status,
        lt.received_on,
        lt.updated_on
    FROM leave_type lt
    INNER JOIN (
        
        SELECT leave_code, MAX(year) AS max_year
        FROM leave_type
        WHERE status = 'A'
        GROUP BY leave_code
    ) latest 
      ON lt.leave_code = latest.leave_code 
     AND lt.year = latest.max_year
    WHERE lt.status = 'A'
    ORDER BY FIELD(lt.leave_code, 'PL', 'SL', 'WFH', 'ML', 'LOP');

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
